Перепиши файл `/home/kasiro/.config/opencode/plugins/phase0-guard.ts` ПОЛНОСТЬЮ, заменив содержимое.

Это V1 OpenCode плагин (TypeScript, Bun runtime). Вот что нужно сделать:

**Основное изменение:** Вместо чтения `opencode.json` напрямую, использовать `client.app.agents()` из V1 PluginClient API.

**Контекст:**
- V1 плагин получает `({ $, client })` где client — это OpencodeClient с методами
- `client.app.agents()` возвращает массив Agent объектов с полями: name, permission (объект с deny/allow), tools (объект {toolName: boolean} где false = deny)
- `client.app.log()` для логирования

**Требования к реализации:**

1. Убрать чтение opencode.json (CONFIG_PATH, agentConfig)
2. Добавить кэширование агентов через `client.app.agents()` с TTL 30 секунд
3. Агента определять по `input.sessionID` из SQLite: `SELECT agent_id FROM session WHERE id = '...'`
4. isToolDenied должен проверять по данным из API (agent.tools и agent.permission)
5. Сохранить Phase 0 Guard и Checkpoint Gate как есть (они работают)
6. При недоступности API — работать в degraded mode (без pre-flight, не блокировать)

**Формат agent из API (client.app.agents()):**
```ts
interface Agent {
  name: string;             // "jarvis", "general", etc
  permission: Record<string, "ask" | "allow" | "deny" | Record<string, "ask" | "allow" | "deny">>;
  tools: Record<string, boolean>;  // toolName: false = deny
  // другие поля не нужны
}
```

**Логика isToolDenied:**
- Если tools[toolName] === false — DENY
- Если tools[key] === false и key с * совпадает — DENY
- Если permission[key] === "deny" для точного или wildcard совпадения — DENY
- Если permission[key] это объект и в нём есть deny правило — DENY
- Во всех остальных случаях — ALLOW

**Важно:**
- Все строковые литералы шаблонов SQL должны экранировать одинарные кавычки (sqlite injection protection)
- Файл должен быть валидным TypeScript, который Bun может выполнить
- Сохранить все существующие импорты и константы
- Сохранить существующие кастомные инструменты (phase0_complete, checkpoint_done)
- Сохранить существующий event handler

Вот полный код для замены (скопируй его в файл):

```typescript
/**
 * phase0-guard — OpenCode plugin
 * ===============================
 *
 * Три механических барьера:
 * 1. PHASE 0 GUARD (Lock & Key) — блокирует инструменты пока CYCLE 1 не выполнен
 * 2. CHECKPOINT GATE — блокирует если сессия >= 30 сообщений без checkpoint.md
 * 3. PRE-FLIGHT — блокирует инструменты, запрещённые для агента (через API)
 *
 * Pre-flight получает deny-правила через `client.app.agents()` (официальный API),
 * а не через чтение opencode.json.
 */

import { type Plugin, tool } from "@opencode-ai/plugin";
import { homedir } from "node:os";

const STATE_PATH = `${homedir()}/.local/share/opencode/phase0-state.json`;
const DB_PATH = `${homedir()}/.local/share/opencode/opencode.db`;
const MEMORY_SESSIONS = `${homedir()}/.local/share/opencode/memory/sessions`;

// === Constants ===

// Phase 0 — инструменты доступные до выполнения CYCLE 1
const PHASE0_ALLOWED = new Set([
  "memory_search",
  "skill",
  "read",
  "phase0_complete",
]);

// Checkpoint Gate — порог сообщений для обязательного checkpoint
const CHECKPOINT_MIN_MESSAGES = 30;
const CHECKPOINT_CACHE_TTL = 10_000; // 10 секунд

// Инструменты доступные во время Checkpoint Gate
const CHECKPOINT_ALLOWED = new Set([
  "task",
  "memory_search",
  "read",
  "skill",
  "checkpoint_done",
]);

// TTL для кэша агентов (client.app.agents())
const AGENTS_CACHE_TTL = 30_000; // 30 секунд

// === State ===

interface SessionCheckpointCache {
  messageCount: number;
  checkpointExists: boolean;
  lastChecked: number;
}

interface State {
  cycle1Completed: boolean;
  sessionId: string | null;
  cpCache: Record<string, SessionCheckpointCache>;
}

interface AgentInfo {
  name: string;
  permission?: Record<string, any>;
  tools?: Record<string, boolean>;
}

// === Plugin ===

export default (async ({ $, client }) => {
  const sh = $;

  // --- Load state ---
  let state: State = {
    cycle1Completed: false,
    sessionId: null,
    cpCache: {},
  };

  try {
    const f = Bun.file(STATE_PATH);
    if (await f.exists()) {
      const saved = JSON.parse(await f.text());
      state = { ...state, ...saved };
      state.cpCache = {}; // не сохраняем кэш
    }
  } catch {
    /* first run */
  }

  async function persist() {
    try {
      await Bun.write(STATE_PATH, JSON.stringify({ ...state, cpCache: {} }, null, 2));
    } catch (e) {
      void client.app.log({
        body: { service: "phase0-guard", level: "error", message: `persist: ${e}` },
      });
    }
  }

  // === Agent permission cache via official API ===

  let agentsCache: AgentInfo[] | null = null;
  let agentsCacheTime = 0;

  async function loadAgents(): Promise<AgentInfo[]> {
    const now = Date.now();
    if (agentsCache && now - agentsCacheTime < AGENTS_CACHE_TTL) {
      return agentsCache;
    }

    try {
      // Official OpenCode API — не читает opencode.json напрямую
      const agents = await client.app.agents() as AgentInfo[];
      agentsCache = agents;
      agentsCacheTime = now;
      return agents;
    } catch (e) {
      void client.app.log({
        body: { service: "phase0-guard", level: "error", message: `agents API: ${e}` },
      });
      // Degraded mode: возвращаем старый кэш или пустой массив
      return agentsCache || [];
    }
  }

  /**
   * Blacklist check: возвращает true если инструмент ЯВНО ЗАПРЕЩЁН для агента.
   * Если запрета нет — инструмент считается разрешённым.
   * Данные получены через official API (client.app.agents()).
   */
  function isToolDenied(toolName: string, agentId: string, agents: AgentInfo[]): boolean {
    const agent = agents.find((a) => a.name === agentId);
    if (!agent) return false; // неизвестный агент — не блокируем

    // 1. Check agent.tools — explicit deny list (toolName: false)
    const tools = agent.tools;
    if (tools) {
      // Прямое совпадение
      if (tools[toolName] === false) return true;

      // Wildcard-совпадения
      for (const [key, allowed] of Object.entries(tools)) {
        if (allowed !== false) continue;
        if (key.endsWith("*") && toolName.startsWith(key.slice(0, -1))) return true;
        if (key.startsWith("*") && toolName.endsWith(key.slice(1))) return true;
      }
    }

    // 2. Check agent.permission — deny rules (edit: "deny", bash.*: "deny")
    const perm = agent.permission;
    if (perm) {
      for (const [key, rule] of Object.entries(perm)) {
        if (typeof rule === "string" && rule === "deny") {
          if (key === toolName) return true;
          if (key.endsWith("*") && toolName.startsWith(key.slice(0, -1))) return true;
          if (key.startsWith("*") && toolName.endsWith(key.slice(1))) return true;
        }
        if (typeof rule === "object" && rule !== null) {
          for (const [pat, action] of Object.entries(rule)) {
            if (action === "deny") {
              if (pat === "*" || pat === toolName) return true;
              if (pat.endsWith("*") && toolName.startsWith(pat.slice(0, -1))) return true;
            }
          }
        }
      }
    }

    return false; // запрета не найдено → инструмент разрешён
  }

  // === Agent resolution by session ID ===

  async function getAgentForSession(sessionID: string): Promise<string | null> {
    try {
      const escapedId = sessionID.replace(/'/g, "''");
      const r = await sh`sqlite3 ${DB_PATH} "SELECT agent_id FROM session WHERE id = '${escapedId}'"`.quiet().nothrow();
      return r.stdout?.toString().trim() || null;
    } catch {
      return null;
    }
  }

  // === Session ID resolution ===

  async function getCurrentSessionId(): Promise<string | null> {
    if (state.sessionId) return state.sessionId;
    try {
      const r = await sh`sqlite3 ${DB_PATH} "SELECT id FROM session WHERE parent_id IS NULL ORDER BY time_updated DESC LIMIT 1"`.quiet().nothrow();
      const sid = r.stdout?.toString().trim() || null;
      if (sid) state.sessionId = sid;
      return sid;
    } catch {
      return null;
    }
  }

  // === Checkpoint Gate helpers ===

  async function getMessageCount(sessionId: string): Promise<number> {
    const cache = state.cpCache[sessionId];
    const now = Date.now();
    if (cache && now - cache.lastChecked < CHECKPOINT_CACHE_TTL) {
      return cache.messageCount;
    }

    try {
      const escapedId = sessionId.replace(/'/g, "''");
      const r = await sh`sqlite3 ${DB_PATH} "SELECT COUNT(*) FROM message WHERE session_id = '${escapedId}'"`.quiet().nothrow();
      const count = parseInt(r.stdout?.toString().trim() || "0");
      const existing = state.cpCache[sessionId] || { checkpointExists: false, lastChecked: 0 };
      state.cpCache[sessionId] = { ...existing, messageCount: count, lastChecked: now };
      return count;
    } catch {
      return 0;
    }
  }

  async function checkpointFileExists(sessionId: string): Promise<boolean> {
    const cache = state.cpCache[sessionId];
    const now = Date.now();
    if (cache && now - cache.lastChecked < CHECKPOINT_CACHE_TTL) {
      return cache.checkpointExists;
    }

    try {
      const cpPath = `${MEMORY_SESSIONS}/${sessionId}/checkpoint.md`;
      const f = Bun.file(cpPath);
      const exists = await f.exists();
      const text = exists ? await f.text() : "";
      const ok = exists && text.trim().length > 0;
      const existing = state.cpCache[sessionId] || { messageCount: 0, lastChecked: 0 };
      state.cpCache[sessionId] = { ...existing, checkpointExists: ok, lastChecked: now };
      return ok;
    } catch {
      return false;
    }
  }

  // === Plugin exports ===

  return {
    tool: {
      phase0_complete: tool({
        description:
          "Подтвердить выполнение CYCLE 1. Снимает Phase 0 guard. Вызывать ONLY после memory_search + skill('jarvis-cycles').",
        args: {},
        async execute() {
          state.cycle1Completed = true;
          await persist();
          return "✅ Phase 0 guard снят. Все инструменты разблокированы.";
        },
      }),

      checkpoint_done: tool({
        description:
          "Подтвердить запись checkpoint для текущей сессии. Снимает Checkpoint Gate. Вызывать ONLY после того, как memory-agent записал checkpoint.md.",
        args: {},
        async execute() {
          const sid = await getCurrentSessionId();
          if (sid) {
            state.cpCache[sid] = {
              messageCount: 999,
              checkpointExists: true,
              lastChecked: Date.now(),
            };
            await persist();
          }
          return "✅ Checkpoint Gate снят. Инструменты разблокированы.";
        },
      }),
    },

    "tool.execute.before": async (input, output) => {
      try {
        // === Определяем агента ===
        const currentAgent = await getAgentForSession(input.sessionID);
        const isJarvis = currentAgent === "jarvis";

        // === 1. Phase 0 guard (Lock & Key) — only for jarvis ===
        if (isJarvis && !state.cycle1Completed) {
          if (!PHASE0_ALLOWED.has(input.tool)) {
            output.isError = true;
            output.content = `⛔ [PHASE 0 GUARD] '${input.tool}' заблокирован.

CYCLE 1 (STOP→RECALL→ORIENT→ACT→VERIFY→SAVE) не выполнен.
Это обязательный протокол при старте каждой сессии.

Выполните:
  1. memory_search("") — проверьте состояние памяти
  2. skill("jarvis-cycles") — загрузите протокол
  3. phase0_complete — подтвердите выполнение

Инструменты, доступные сейчас: memory_search, skill, read, phase0_complete`;
            return;
          }
          return;
        }

        // === 2. Checkpoint Gate — only for jarvis ===
        const sid = isJarvis ? await getCurrentSessionId() : null;
        if (sid) {
          const msgCount = await getMessageCount(sid);
          if (msgCount >= CHECKPOINT_MIN_MESSAGES) {
            const cpExists = await checkpointFileExists(sid);
            if (!cpExists) {
              if (!CHECKPOINT_ALLOWED.has(input.tool)) {
                output.isError = true;
                output.content = `⛔ [CHECKPOINT GATE] '${input.tool}' заблокирован.

Сессия ${sid}: ${msgCount} сообщений, но checkpoint не записан.

ВАШИ ДЕЙСТВИЯ:
  1. Проанализируйте историю текущей сессии
  2. Выделите ключевые решения, ошибки, паттерны
  3. Делегируйте memory-agent'у запись checkpoint:
     task(subagent_type="memory-agent", prompt="Запиши checkpoint для сессии ${sid}: ...
        ключевые решения/ошибки/паттерны...")
  4. После записи вызовите checkpoint_done для разблокировки

Инструменты, доступные сейчас: task, memory_search, read, skill, checkpoint_done`;
                return;
              }
            }
          }
        }

        // === 3. Pre-flight check — для всех агентов ===
        if (currentAgent) {
          const agents = await loadAgents();
          if (agents.length > 0 && isToolDenied(input.tool, currentAgent, agents)) {
            output.isError = true;
            output.content = `⛔ [PRE-FLIGHT] '${input.tool}' запрещён для агента '${currentAgent}' согласно настройкам безопасности.

Делегируйте задачу через task() другому агенту, у которого нет такого запрета.`;
            return;
          }
        }
      } catch (e) {
        void client.app.log({
          body: { service: "phase0-guard", level: "error", message: `before: ${e}` },
        });
      }
    },

    event: async ({ event }) => {
      try {
        if (event.type === "session.created") {
          // Новая сессия — сброс Phase 0 + очистка кэша
          state.cycle1Completed = false;
          const newSid = (event.properties as any)?.sessionID || null;
          if (newSid) {
            state.sessionId = newSid;
            delete state.cpCache[newSid];
          }
          await persist();

          void client.app.log({
            body: {
              service: "phase0-guard",
              level: "info",
              message: `Phase 0 reset for ${newSid}`,
            },
          });
        }

        // Инвалидация кэша сообщений при обновлении
        if (event.type === "message.updated") {
          const props = event.properties as any;
          if (props?.sessionID && state.cpCache[props.sessionID]) {
            state.cpCache[props.sessionID].lastChecked = 0;
          }
        }
      } catch (e) {
        void client.app.log({
          body: { service: "phase0-guard", level: "error", message: `event: ${e}` },
        });
      }
    },
  };
}) satisfies Plugin;
```

